// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * SPIKE support (Routine C): a poor-man's sampling profiler for the scratch timing tests. {@code -DargLine} does not
 * reach the surefire fork in this build, so JFR is unavailable; sampling the query thread from a daemon thread gives
 * the same hot-path answer with no build changes.
 */
final class ScratchProfilers {

	private ScratchProfilers() {
	}

	/** Samples {@code target} every millisecond until {@code stop} is set, tallying leaf methods and rdf4j paths. */
	static Thread startSampler(Thread target, Map<String, Integer> leaves, Map<String, Integer> paths,
			AtomicBoolean stop) {
		Thread sampler = new Thread(() -> {
			while (!stop.get()) {
				StackTraceElement[] trace = target.getStackTrace();
				if (trace.length > 0) {
					leaves.merge(trace[0].getClassName() + "." + trace[0].getMethodName(), 1, Integer::sum);
					StringBuilder path = new StringBuilder();
					int kept = 0;
					for (StackTraceElement element : trace) {
						String cls = element.getClassName();
						if (!cls.startsWith("org.eclipse.rdf4j") || cls.contains(".Scratch")) {
							continue;
						}
						if (kept++ > 0) {
							path.append("\n[scratch-prof]        <- ");
						}
						path.append(cls.substring(cls.lastIndexOf('.') + 1))
								.append('.')
								.append(element.getMethodName())
								.append(':')
								.append(element.getLineNumber());
						if (kept >= 16) {
							break;
						}
					}
					if (kept > 0) {
						paths.merge(path.toString(), 1, Integer::sum);
					}
				}
				try {
					Thread.sleep(1);
				} catch (InterruptedException interrupted) {
					return;
				}
			}
		}, "scratch-sampler");
		sampler.setDaemon(true);
		sampler.start();
		return sampler;
	}

	static void report(String title, Map<String, Integer> counts, int limit) {
		System.out.println("[scratch-prof] " + title);
		counts.entrySet()
				.stream()
				.sorted((a, b) -> Integer.compare(b.getValue(), a.getValue()))
				.limit(limit)
				.forEach(entry -> System.out.println("[scratch-prof]   " + entry.getValue() + "  " + entry.getKey()));
	}
}
